/* generated by build.py - edit js/modules/*.js and js/app.js, then run: python3 build.py */
(function(){
const K=KANJI_320;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s||'').replace(/[★◆]/g,'');
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const pct=(a,b)=>b?Math.round(100*a/b):0;
const bar=p=>`<div class="bar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></div>`;

const KEY='minna-n5-v1';
const blank=()=>({v:1,settings:{name:'',goal:20,exam:'',romaji:true},kanji:{},vocab:{},grammar:{},log:[],mistakes:{},results:[]});
let state;
function load(){try{state=JSON.parse(localStorage.getItem(KEY))||blank()}catch{state=blank()}return state}
function get(){return state||load()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('save failed',e)}}
function kstat(n){const k=get().kanji;return k[n]||(k[n]={seen:false,status:'new',right:0,wrong:0,last:null,bookmark:false})}
function record(n,ok){const s=kstat(n);s.seen=true;ok?s.right++:s.wrong++;s.last=new Date().toISOString();
 if(s.status==='new')s.status='learning';
 const t=s.right+s.wrong;if(t>=3&&s.right/t>=.85&&s.right>=3)s.status='mastered';else if(!ok&&s.status==='mastered')s.status='revision';
 if(!ok&&s.wrong>s.right)s.status='revision';
 const day=new Date().toISOString().slice(0,10);const L=get().log;L.push({d:day,n,ok});if(L.length>3000)L.splice(0,L.length-3000);save()}
function vstat(k){const v=get().vocab||(get().vocab={});return v[k]||(v[k]={learned:false,bookmark:false,right:0,wrong:0,last:null})}
function gstat(k){const v=get().grammar||(get().grammar={});return v[k]||(v[k]={right:0,wrong:0,last:null})}
function logAns(ok){const day=new Date().toISOString().slice(0,10);const L=get().log;L.push({d:day,n:0,ok});if(L.length>3000)L.splice(0,L.length-3000)}
function exportJSON(){return JSON.stringify(get(),null,1)}
function importJSON(txt){const o=JSON.parse(txt);
 if(!o||o.v!==1||typeof o.kanji!=='object'||!Array.isArray(o.log)||typeof o.settings!=='object')throw new Error('Not a valid MINNA N5 progress file');
 for(const [k,s] of Object.entries(o.kanji)){if(!(+k>=1&&+k<=320)||typeof s.right!=='number'||typeof s.wrong!=='number')throw new Error('Invalid kanji record '+k)}
 state=Object.assign(blank(),o);save()}
function reset(){state=blank();save()}



// question: {id,n,type,prompt,options:[str],answer:str,explain}
function runQuiz(root,questions,{title='Quiz',seconds=0,onDone,back='#/kanji',backLabel='Back'}={}){
 let i=0,sel=null,done=false,score=0,wrong=[],left=seconds,timer=null;
 const qs=questions.map(q=>({...q,options:shuffle(q.options)}));
 function tick(){if(!seconds)return;timer=setInterval(()=>{left--;const t=root.querySelector('#t');if(t)t.textContent=fmt(left);if(left<=0){clearInterval(timer);finish(true)}},1000)}
 const fmt=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
 function show(){
  const q=qs[i];let answered=sel!==null&&q._shown;
  root.innerHTML=`<div class="card"><div class="row"><strong>${esc(title)}</strong><span class="muted">Question ${i+1} / ${qs.length}</span>${seconds?`<span class="tag">Time left <span id="t">${fmt(left)}</span></span>`:''}</div>${bar(pct(i,qs.length))}
  <p style="font-size:20px;margin-top:16px">${esc(q.prompt)}</p><div id="opts">${q.options.map((o,k)=>`<button class="opt" data-k="${k}">${esc(o)}</button>`).join('')}</div>
  <div id="fb" aria-live="polite"></div><div class="row"><button id="sub" disabled>Submit</button></div></div>`;
  const opts=[...root.querySelectorAll('.opt')];
  opts.forEach(b=>b.onclick=()=>{if(q._shown)return;sel=q.options[b.dataset.k];opts.forEach(x=>x.classList.remove('sel'));b.classList.add('sel');root.querySelector('#sub').disabled=false});
  root.querySelector('#sub').onclick=()=>{
   if(!q._shown){q._shown=true;const ok=sel===q.answer;if(ok)score++;else wrong.push({q,picked:sel});if(q.n)record(q.n,ok);if(q.rec){q.rec(ok);logAns(ok);save()}
    opts.forEach(b=>{const v=q.options[b.dataset.k];if(v===q.answer)b.classList.add('ok');else if(v===sel)b.classList.add('bad')});
    root.querySelector('#fb').innerHTML=`<p><b>${ok?'Correct.':'Not quite.'}</b> ${esc(q.explain||'')}</p>`;
    const s=root.querySelector('#sub');s.textContent=i+1<qs.length?'Next':'Finish';
   }else{sel=null;if(i+1<qs.length){i++;show()}else finish(false)}};
 }
 function finish(timeUp){clearInterval(timer);if(done)return;done=true;
  const attempted=qs.filter(q=>q._shown).length;
  get().results.push({d:new Date().toISOString(),title,score,total:qs.length});save();
  root.innerHTML=`<div class="card"><h2>${esc(title)} — result</h2>${timeUp?'<p class="warn">Time ran out. Unanswered questions count as incorrect.</p>':''}
  <p style="font-size:24px"><b>${score} / ${qs.length}</b> (${pct(score,qs.length)}%)</p><p class="muted">Answered ${attempted} of ${qs.length}.</p>
  <div class="row"><button id="retry">Retry</button><a class="btn alt" href="${back}">${backLabel}</a></div></div>
  ${wrong.length?`<div class="card"><h3>Review incorrect answers</h3>${wrong.map(w=>`<p><b>${esc(w.q.prompt)}</b><br>Your answer: ${esc(w.picked)}<br>Correct: ${esc(w.q.answer)}<br><span class="muted">${esc(w.q.explain||'')}</span></p>`).join('')}</div>`:''}`;
  root.querySelector('#retry').onclick=()=>runQuiz(root,questions,{title,seconds,onDone,back,backLabel});if(onDone)onDone({score,total:qs.length});}
 show();tick();
}





const meaningOf=k=>k.note||(k.vocab[0]?k.vocab[0].meaning:'');
const good=k=>k.vocab.filter(v=>!v.needs_review);
const counts=()=>{const s=K.map(k=>kstat(k.n));return{total:320,studied:s.filter(x=>x.seen).length,mastered:s.filter(x=>x.status==='mastered').length,revision:s.filter(x=>x.status==='revision').length,right:s.reduce((a,x)=>a+x.right,0),wrong:s.reduce((a,x)=>a+x.wrong,0)}};
function nextSuggested(){const f=K.find(k=>!kstat(k.n).seen);return f?f.n:1}
const num=(v,d)=>{v=parseInt(v);return isNaN(v)?d:Math.min(320,Math.max(1,v))};
function search(q){q=q.trim().toLowerCase();if(!q)return K;return K.filter(k=>k.kanji===q||(k.kun||'').includes(q)||(k.on||'').includes(q)||meaningOf(k).toLowerCase().includes(q)||k.vocab.some(v=>v.word.includes(q)||v.reading.includes(q)||v.meaning.toLowerCase().includes(q)))}
function index(root){
 const c=counts();
 root.innerHTML=`<h2>Kanji 1–320</h2><p class="muted">Source: <i>Basic Kanji 320</i> by Meguro Language Center, in the original order. Not all 320 are official JLPT N5 kanji.</p>
 <div class="card"><b>${c.studied} / 320 studied</b> · ${c.mastered} mastered · ${c.revision} need revision${bar(pct(c.studied,320))}</div>
 <div class="card"><div class="row"><input id="q" type="search" placeholder="Search kanji, meaning, reading, word" aria-label="Search" style="flex:1;min-width:200px">
 <label>From <input id="a" type="number" min="1" max="320" value="1" style="width:70px"></label><label>to <input id="b" type="number" min="1" max="320" value="320" style="width:70px"></label>
 <select id="st" aria-label="Status"><option value="">All status</option><option>new</option><option>learning</option><option>mastered</option><option>revision</option></select>
 <label><input id="bm" type="checkbox"> Bookmarked</label></div>
 <div class="row">${[[1,50],[51,100],[101,150],[151,200],[201,250],[251,300],[301,320]].map(r=>`<button class="alt pre" data-a="${r[0]}" data-b="${r[1]}">${r[0]}–${r[1]}</button>`).join('')}</div>
 <div class="row"><a class="btn" id="fl" href="#/kanji-flash/1/320">Flashcards</a><a class="btn" href="#/kanji-quiz">Quizzes &amp; tests</a><span id="cnt" class="muted"></span></div></div><div class="grid" id="g"></div>`;
 const $=s=>root.querySelector(s);
 function draw(){const a=num($('#a').value,1),b=num($('#b').value,320),st=$('#st').value,bm=$('#bm').checked;
  const list=search($('#q').value).filter(k=>k.n>=a&&k.n<=b&&(!st||kstat(k.n).status===st)&&(!bm||kstat(k.n).bookmark));
  $('#cnt').textContent=list.length+' shown';$('#fl').href=`#/kanji-flash/${a}/${b}`;
  $('#g').innerHTML=list.map(k=>{const s=kstat(k.n);return`<a class="kcell s-${s.status}" href="#/kanji/${k.n}"><small>${k.n}${s.bookmark?' ★':''}</small><span class="ch">${k.kanji}</span><small>${esc(meaningOf(k)).slice(0,22)}</small></a>`}).join('')||'<p>No matches.</p>'}
 ['#q','#a','#b','#st','#bm'].forEach(s=>$(s).addEventListener('input',draw));
 root.querySelectorAll('.pre').forEach(b=>b.onclick=()=>{$('#a').value=b.dataset.a;$('#b').value=b.dataset.b;draw()});draw();
}
function detail(root,n){
 n=num(n,1);const k=K[n-1],s=kstat(n);
 root.innerHTML=`<div class="row"><a class="btn alt" href="#/kanji">All kanji</a>${n>1?`<a class="btn alt" href="#/kanji/${n-1}">← ${n-1}</a>`:''}${n<320?`<a class="btn alt" href="#/kanji/${n+1}">${n+1} →</a>`:''}</div>
 <div class="card"><p class="muted">No. ${n}</p><div class="big">${k.kanji}</div>
 <p><b>Kun'yomi (hiragana):</b> ${esc(k.kun||'—')}<br><b>On'yomi (katakana):</b> ${esc(k.on||'—')}<br><b>Meaning note:</b> ${esc(k.note||'(none printed in source)')}</p>
 <p class="muted">Stroke count, stroke order and romaji: not available in the source, so not shown. ★ in a reading = not needed for N5; ◆ = not needed for N5/N4 (per the PDF).</p>
 ${k.review.length?`<p class="warn">Extraction notes: ${esc(k.review.join('; '))}. Check against the PDF.</p>`:''}
 <div class="row"><select id="st" aria-label="Status">${['new','learning','mastered','revision'].map(x=>`<option${s.status===x?' selected':''}>${x}</option>`).join('')}</select><button class="alt" id="bm">${s.bookmark?'Remove bookmark':'Bookmark'}</button></div>
 <p class="muted">Right ${s.right} · Wrong ${s.wrong} · Accuracy ${pct(s.right,s.right+s.wrong)}% · Last practised ${s.last?s.last.slice(0,10):'never'}</p></div>
 <div class="card"><h3>Vocabulary and examples (from the PDF)</h3>${k.vocab.length?`<table><tr><th>Word</th><th>Reading</th><th>Meaning</th><th>Example</th></tr>${k.vocab.map(v=>`<tr><td>${esc(clean(v.word))}</td><td>${esc(v.reading)}</td><td>${esc(v.meaning)}</td><td>${esc(clean(v.example))}</td></tr>`).join('')}</table>`:'<p>The source lists no vocabulary for this kanji.</p>'}</div>`;
 s.seen=true;save();
 root.querySelector('#st').onchange=e=>{s.status=e.target.value;save()};
 root.querySelector('#bm').onclick=e=>{s.bookmark=!s.bookmark;save();detail(root,n)};
}
function flash(root,a,b){
 a=num(a,1);b=num(b,320);if(b<a)[a,b]=[b,a];let list=K.filter(k=>k.n>=a&&k.n<=b),i=0,show=false;
 function d(){const k=list[i],s=kstat(k.n);
  root.innerHTML=`<div class="row"><a class="btn alt" href="#/kanji">Back</a><span class="muted">Card ${i+1} / ${list.length} (kanji ${a}–${b})</span></div>
  <div class="card"><div class="big">${k.kanji}</div>${show?`<p><b>${esc(k.kun||'')}</b> ${esc(k.on||'')} ${k.note?`<span class="muted">(${esc(k.note)})</span>`:''}</p><table>${k.vocab.map(v=>`<tr><td>${esc(clean(v.word))}</td><td>${esc(v.reading)}</td><td>${esc(v.meaning)}</td></tr>`).join('')}</table>${k.vocab[0]?`<p class="muted">${esc(clean(k.vocab[0].example))}</p>`:''}`:'<p class="muted" style="text-align:center">Think of the reading and a word, then reveal.</p>'}
  <div class="row"><button id="p">←</button><button id="r">${show?'Hide':'Reveal'}</button><button id="nx">→</button><button class="alt" id="sh">Shuffle</button><button class="alt" id="bm">${s.bookmark?'★ Bookmarked':'☆ Bookmark'}</button>
  <select id="st" aria-label="Status">${['new','learning','mastered','revision'].map(x=>`<option${s.status===x?' selected':''}>${x}</option>`).join('')}</select></div></div>`;
  const $=q=>root.querySelector(q);
  $('#p').onclick=()=>{i=(i-1+list.length)%list.length;show=false;d()};$('#nx').onclick=()=>{i=(i+1)%list.length;show=false;d()};
  $('#r').onclick=()=>{show=!show;if(show){s.seen=true;if(s.status==='new')s.status='learning';save()}d()};
  $('#sh').onclick=()=>{list=shuffle(list);i=0;show=false;d()};
  $('#bm').onclick=()=>{s.bookmark=!s.bookmark;save();d()};$('#st').onchange=e=>{s.status=e.target.value;save()};}
 d();
}
// ---------- quizzes (only from verified source rows) ----------
function pick(arr,n,not){return shuffle(arr.filter(x=>!not.includes(x))).slice(0,n)}
function make(k,type,all){
 const rows=good(k);if(!rows.length&&type!=='kanjireading')return null;
 const v=rows[Math.floor(Math.random()*rows.length)];
 const U=a=>[...new Set(a)];
 if(type==='reading'){const pool=U(all.flatMap(x=>good(x).map(r=>r.reading)));const d=pick(pool,3,[v.reading]);if(d.length<3)return null;
  return{n:k.n,prompt:`What is the reading of ${clean(v.word)}?`,options:[v.reading,...d],answer:v.reading,explain:`${clean(v.word)} = ${v.reading} (${v.meaning}). Source: kanji ${k.n}.`}}
 if(type==='vocab'){const pool=U(all.flatMap(x=>good(x).map(r=>r.meaning)));const d=pick(pool,3,[v.meaning]);if(d.length<3)return null;
  return{n:k.n,prompt:`What does ${clean(v.word)} (${v.reading}) mean?`,options:[v.meaning,...d],answer:v.meaning,explain:`${clean(v.word)} means "${v.meaning}".`}}
 if(type==='sentence'){const ex=clean(v.example);if(!ex)return null;const pool=U(all.flatMap(x=>good(x).map(r=>r.meaning)));const d=pick(pool,3,[v.meaning]);if(d.length<3)return null;
  return{n:k.n,prompt:`In 「${ex}」, what does ${clean(v.word)} mean?`,options:[v.meaning,...d],answer:v.meaning,explain:`${clean(v.word)} = ${v.meaning}.`}}
 if(type==='kanjireading'){const mine=[k.kun,k.on].filter(Boolean).join(' / ');const pool=U(all.map(x=>[x.kun,x.on].filter(Boolean).join(' / ')).filter(Boolean));const d=pick(pool,3,[mine]);if(!mine||d.length<3)return null;
  return{n:k.n,prompt:`Which readings are listed for ${k.kanji}?`,options:[mine,...d],answer:mine,explain:`The PDF lists: ${mine}.`}}
 if(type==='recognition'){const r=rows.find(r=>[...r.word].filter(c=>c===k.kanji).length&&r.word.length>1)||rows[0];if(!r.word.includes(k.kanji))return null;
  const d=pick(all.map(x=>x.kanji),3,[k.kanji]);return{n:k.n,prompt:`Which kanji is used in ${r.reading} (${r.meaning})?  Word: ${clean(r.word).replace(k.kanji,'＿')}`,options:[k.kanji,...d],answer:k.kanji,explain:`${clean(r.word)} contains ${k.kanji} (No. ${k.n}).`}}
 return null;
}
function quizMenu(root){
 root.innerHTML=`<h2>Kanji quizzes</h2><div class="card"><div class="row">
 <label>Type <select id="t"><option value="reading">Reading quiz (word → reading)</option><option value="vocab">Vocabulary quiz (word → meaning)</option><option value="sentence">Sentence practice</option><option value="kanjireading">Kanji → listed readings</option><option value="recognition">Recognition challenge</option><option value="mixed">Mixed</option></select></label>
 <label>Questions <select id="c"><option>10</option><option>25</option><option>50</option><option>100</option></select></label>
 <label>Range <input id="a" type="number" min="1" max="320" value="1" style="width:70px"> – <input id="b" type="number" min="1" max="320" value="320" style="width:70px"></label>
 <label><input type="checkbox" id="tm"> Timed (30 s per question)</label><label><input type="checkbox" id="wk"> Weak kanji only</label></div>
 <button id="go">Start</button><p class="muted">There is no kanji → English meaning quiz yet: the PDF does not print one main meaning per kanji, so I won't make one up. All questions use readings, words, meanings and sentences printed in the PDF. Entries marked for review are skipped.</p><p id="msg" class="warn" hidden></p></div><div id="qz"></div>`;
 const $=s=>root.querySelector(s);
 $('#go').onclick=()=>{const a=num($('#a').value,1),b=num($('#b').value,320),cnt=+$('#c').value,t=$('#t').value;
  let pool=K.filter(k=>k.n>=Math.min(a,b)&&k.n<=Math.max(a,b));
  if($('#wk').checked)pool=pool.filter(k=>{const s=kstat(k.n);return s.wrong>0&&s.wrong>=s.right});
  const types=['reading','vocab','sentence','kanjireading','recognition'];const qs=[];let guard=0;
  while(qs.length<cnt&&pool.length&&guard++<cnt*20){const k=pool[Math.floor(Math.random()*pool.length)];
   const q=make(k,t==='mixed'?types[Math.floor(Math.random()*types.length)]:t,K);if(q&&!qs.some(x=>x.prompt===q.prompt))qs.push(q)}
  const m=$('#msg');if(!qs.length){m.hidden=false;m.textContent='No questions could be built for that selection (weak-kanji mode needs earlier mistakes).';return}
  m.hidden=qs.length>=cnt?true:false;if(!m.hidden)m.textContent=`Only ${qs.length} distinct questions available for this range; running those.`;
  qs.forEach((q,i)=>q.id=i);runQuiz($('#qz'),qs,{title:`Kanji ${t} test (${Math.min(a,b)}–${Math.max(a,b)})`,seconds:$('#tm').checked?qs.length*30:0});
  $('#qz').scrollIntoView();};
}




// Build one record per word (words in several lessons are merged and list every lesson)
const VOCAB=(()=>{const m=new Map();for(const L of MINNA_VOCAB)for(const line of L.w.trim().split('\n')){const [w,r,en,t]=line.split('|');const rd=r||w;const key=w+'|'+rd;let e=m.get(key);if(!e){e={key,w,r:rd,en:[],t,ls:[]};m.set(key,e)}if(!e.en.includes(en))e.en.push(en);if(!e.ls.includes(L.l))e.ls.push(L.l)}return [...m.values()].map(e=>({...e,meaning:e.en.join('; ')}))})();
const VOCAB_ENTRIES=MINNA_VOCAB.reduce((a,L)=>a+L.w.trim().split('\n').length,0);
const TYPES={n:'noun',v:'verb',i:'i-adj',na:'na-adj',adv:'adverb',pron:'pronoun',ptcl:'particle',ph:'phrase',ctr:'counter',conj:'conjunction'};
const lessonOpts=sel=>`<option value="all">All lessons</option>`+MINNA_VOCAB.map(L=>`<option value="${L.l}"${String(sel)===String(L.l)?' selected':''}>Lesson ${L.l} – ${esc(L.t)}</option>`).join('');
const inLesson=(e,l)=>l==='all'||e.ls.includes(+l);
const vocabCounts=()=>({total:VOCAB.length,learned:VOCAB.filter(e=>vstat(e.key).learned).length});
function vocabIndex(root){
 const c=vocabCounts();
 root.innerHTML=`<h2>Vocabulary (Minna no Nihongo I, Lessons 1–25)</h2><p class="muted">${VOCAB.length} distinct words (${VOCAB_ENTRIES} lesson entries; words that appear in several lessons are merged). Word lists were written for this app and checked against the reference PDF's English glosses; a few may differ from your textbook edition.</p>
 <div class="card"><b>${c.learned} / ${c.total} learned</b>${bar(pct(c.learned,c.total))}</div>
 <div class="card"><div class="row"><input id="q" type="search" placeholder="Search Japanese or English" aria-label="Search" style="flex:1;min-width:200px"><select id="l" aria-label="Lesson">${lessonOpts('all')}</select>
 <select id="t" aria-label="Word type"><option value="">All types</option>${Object.entries(TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select>
 <select id="s" aria-label="Status"><option value="">All</option><option value="unlearned">Not learned</option><option value="learned">Learned</option><option value="bookmark">Bookmarked</option><option value="difficult">Difficult</option></select></div>
 <div class="row"><a class="btn" id="fl" href="#/vocab-flash/all">Flashcards</a><a class="btn" href="#/vocab-quiz">Vocabulary quizzes</a><span id="cnt" class="muted"></span></div></div><div class="card" style="overflow:auto"><table><thead><tr><th>Word</th><th>Reading</th><th>Meaning</th><th>Type</th><th>Lesson</th><th>Learned</th><th>★</th></tr></thead><tbody id="b"></tbody></table></div>`;
 const $=s=>root.querySelector(s);
 function draw(){const q=$('#q').value.trim().toLowerCase(),l=$('#l').value,t=$('#t').value,s=$('#s').value;
  const list=VOCAB.filter(e=>{const v=vstat(e.key);return inLesson(e,l)&&(!t||e.t===t)&&(!q||e.w.includes(q)||e.r.includes(q)||e.meaning.toLowerCase().includes(q))&&(!s||(s==='learned'?v.learned:s==='unlearned'?!v.learned:s==='bookmark'?v.bookmark:v.wrong>v.right))});
  $('#cnt').textContent=list.length+' shown';$('#fl').href='#/vocab-flash/'+l;
  $('#b').innerHTML=list.map(e=>{const v=vstat(e.key);return`<tr><td style="font-size:20px">${esc(e.w)}</td><td>${esc(e.r)}</td><td>${esc(e.meaning)}</td><td>${TYPES[e.t]||''}</td><td>${e.ls.join(', ')}</td><td><input type="checkbox" data-k="${esc(e.key)}" class="lr" aria-label="Learned"${v.learned?' checked':''}></td><td><button class="alt bk" data-k="${esc(e.key)}" aria-label="Bookmark">${v.bookmark?'★':'☆'}</button></td></tr>`}).join('')||'<tr><td colspan="7">No matches.</td></tr>'}
 ['#q','#l','#t','#s'].forEach(s=>$(s).addEventListener('input',draw));
 $('#b').addEventListener('change',e=>{if(e.target.classList.contains('lr')){vstat(e.target.dataset.k).learned=e.target.checked;save()}});
 $('#b').addEventListener('click',e=>{const b=e.target.closest('.bk');if(b){const v=vstat(b.dataset.k);v.bookmark=!v.bookmark;save();b.textContent=v.bookmark?'★':'☆'}});
 draw();
}
function vocabFlash(root,lesson){
 lesson=lesson||'all';let list=VOCAB.filter(e=>inLesson(e,lesson)),i=0,show=false,enFirst=false;
 function d(){if(!list.length){root.innerHTML='<p>No words.</p><a class="btn" href="#/vocab">Back</a>';return}const e=list[i],v=vstat(e.key);
  const front=enFirst?esc(e.meaning):`<span style="font-size:48px">${esc(e.w)}</span>`;
  const back=enFirst?`<span style="font-size:40px">${esc(e.w)}</span><br>${esc(e.r)}`:`${esc(e.r)}<br><b>${esc(e.meaning)}</b>`;
  root.innerHTML=`<div class="row"><a class="btn alt" href="#/vocab">Back</a><select id="l" aria-label="Lesson">${lessonOpts(lesson)}</select><label><input type="checkbox" id="dir"${enFirst?' checked':''}> English first</label><span class="muted">Card ${i+1} / ${list.length}</span></div>
  <div class="card" style="text-align:center;min-height:200px"><p>${front}</p>${show?`<p style="font-size:22px">${back}</p><p class="muted">Lesson ${e.ls.join(', ')} · ${TYPES[e.t]||''}</p>`:'<p class="muted">Try to recall, then reveal.</p>'}
  <div class="row" style="justify-content:center"><button id="p">←</button><button id="r">${show?'Hide':'Reveal'}</button><button id="n">→</button><button class="alt" id="sh">Shuffle</button><button class="alt" id="lr">${v.learned?'✓ Learned':'Mark learned'}</button><button class="alt" id="bm">${v.bookmark?'★':'☆'}</button></div></div>`;
  const $=q=>root.querySelector(q);
  $('#p').onclick=()=>{i=(i-1+list.length)%list.length;show=false;d()};$('#n').onclick=()=>{i=(i+1)%list.length;show=false;d()};$('#r').onclick=()=>{show=!show;d()};
  $('#sh').onclick=()=>{list=shuffle(list);i=0;show=false;d()};$('#lr').onclick=()=>{v.learned=!v.learned;save();d()};$('#bm').onclick=()=>{v.bookmark=!v.bookmark;save();d()};
  $('#dir').onchange=ev=>{enFirst=ev.target.checked;show=false;d()};$('#l').onchange=ev=>{lesson=ev.target.value;list=VOCAB.filter(x=>inLesson(x,lesson));i=0;show=false;d()};}
 d();
}
const disp=e=>e.r===e.w?e.w:`${e.w}（${e.r}）`;
function vocabQs(mode,pool,count,all){
 const qs=[];const seen=new Set();let g=0;
 while(qs.length<count&&pool.length&&g++<count*30){const e=pool[Math.floor(Math.random()*pool.length)];if(seen.has(e.key))continue;
  const same=all.filter(x=>x.t===e.t&&x.key!==e.key);const others=shuffle(same.length>=8?same:all.filter(x=>x.key!==e.key));
  let q;
  if(mode==='jp-en'){const ds=[...new Set(others.map(x=>x.meaning))].filter(m=>m!==e.meaning).slice(0,3);q={prompt:`What does ${disp(e)} mean?`,options:[e.meaning,...ds],answer:e.meaning,explain:`${disp(e)} = ${e.meaning}.`}}
  else if(mode==='en-jp'){const ds=[...new Set(others.filter(x=>x.meaning!==e.meaning).map(disp))].filter(m=>m!==disp(e)).slice(0,3);q={prompt:`Which Japanese word means "${e.meaning}"?`,options:[disp(e),...ds],answer:disp(e),explain:`"${e.meaning}" = ${disp(e)}.`}}
  else{if(e.w===e.r)continue;const ds=[...new Set(others.map(x=>x.r))].filter(m=>m!==e.r).slice(0,3);q={prompt:`How do you read ${e.w}?`,options:[e.r,...ds],answer:e.r,explain:`${e.w} is read ${e.r} (${e.meaning}).`}}
  if(q.options.length<4)continue;seen.add(e.key);q.rec=ok=>{const v=vstat(e.key);ok?v.right++:v.wrong++;v.last=new Date().toISOString()};qs.push(q)}
 return qs}
function vocabQuizMenu(root){
 root.innerHTML=`<h2>Vocabulary quizzes</h2><div class="card"><div class="row"><label>Type <select id="m"><option value="jp-en">Japanese → English</option><option value="en-jp">English → Japanese</option><option value="reading">Kanji word → reading</option></select></label>
 <label>Lessons <select id="a" aria-label="From lesson">${MINNA_VOCAB.map(L=>`<option value="${L.l}">${L.l}</option>`).join('')}</select> to <select id="b" aria-label="To lesson">${MINNA_VOCAB.map(L=>`<option value="${L.l}"${L.l===25?' selected':''}>${L.l}</option>`).join('')}</select></label>
 <label>Questions <select id="c"><option>10</option><option>25</option><option>50</option></select></label><label><input type="checkbox" id="df"> Difficult words only</label></div><button id="go">Start</button><p id="msg" class="warn" hidden></p></div><div id="qz"></div>`;
 const $=s=>root.querySelector(s);
 $('#go').onclick=()=>{let a=+$('#a').value,b=+$('#b').value;if(a>b)[a,b]=[b,a];let pool=VOCAB.filter(e=>e.ls.some(l=>l>=a&&l<=b));if($('#df').checked)pool=pool.filter(e=>{const v=vstat(e.key);return v.wrong>v.right});
  const qs=vocabQs($('#m').value,pool,+$('#c').value,VOCAB);const m=$('#msg');
  if(!qs.length){m.hidden=false;m.textContent='No questions for that selection (difficult-word mode needs earlier mistakes).';return}
  m.hidden=qs.length>=+$('#c').value;if(!m.hidden)m.textContent=`Only ${qs.length} questions available; running those.`;
  runQuiz($('#qz'),qs,{title:`Vocabulary ${$('#m').value} (lessons ${a}–${b})`,back:'#/vocab',backLabel:'Back to vocabulary'});$('#qz').scrollIntoView()};
}




const GRAMMAR=MINNA_GRAMMAR;
const gkey=g=>g.l+':'+g.p;
const title=l=>l===0?'Particles at a glance':`Lesson ${l}`;
function grammarIndex(root,lesson){
 lesson=lesson||'all';const nLessons=[...new Set(GRAMMAR.map(g=>g.l))].sort((a,b)=>a-b);
 const list=GRAMMAR.filter(g=>lesson==='all'||String(g.l)===String(lesson));
 root.innerHTML=`<h2>Grammar &amp; Particles (Minna no Nihongo I)</h2><p class="muted">${GRAMMAR.filter(g=>!g.particle).length} grammar patterns across Lessons 1–25 plus ${GRAMMAR.filter(g=>g.particle).length} core particles. Explanations and examples are original, written for this app (not copied from the textbook). Lessons with fewer patterns (such as 15, 20, 22–25) still need expanding.</p>
 <div class="card"><div class="row"><select id="l" aria-label="Lesson"><option value="all">All lessons</option>${nLessons.map(l=>`<option value="${l}"${String(lesson)===String(l)?' selected':''}>${title(l)}</option>`).join('')}</select><a class="btn" href="#/grammar-quiz">Practice questions</a><span class="muted">${list.length} shown</span></div></div>`+
 list.map(g=>{const s=gstat(gkey(g));return`<details class="card"><summary><b>${esc(g.p)}</b> <span class="tag">${title(g.l)}</span> — ${esc(g.m)}</summary>
  <p><b>Formation:</b> ${esc(g.f)}</p><p>${esc(g.e)}</p><table>${g.x.map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td></tr>`).join('')}</table>${g.n?`<p class="warn">${esc(g.n)}</p>`:''}${g.d.length?`<p class="muted">Practice: ${g.d.length} question(s) · ${s.right} right / ${s.wrong} wrong</p>`:''}</details>`}).join('');
 root.querySelector('#l').onchange=e=>{location.hash='#/grammar/'+e.target.value};
}
function grammarQs(lesson,count){
 const items=[];for(const g of GRAMMAR)if(lesson==='all'||String(g.l)===String(lesson))for(const d of g.d)items.push({g,d});
 return shuffle(items).slice(0,count).map(({g,d})=>{const wrong=[...new Set(d[2])].filter(x=>x!==d[1]);return{prompt:d[0],options:[d[1],...wrong],answer:d[1],explain:`${d[3]} (${g.p})`,rec:ok=>{const s=gstat(gkey(g));ok?s.right++:s.wrong++;s.last=new Date().toISOString()}}})}
function grammarQuizMenu(root){
 const nLessons=[...new Set(GRAMMAR.filter(g=>g.d.length).map(g=>g.l))].sort((a,b)=>a-b);
 root.innerHTML=`<h2>Grammar &amp; particle practice</h2><div class="card"><div class="row"><label>Scope <select id="l"><option value="all">All lessons</option>${nLessons.map(l=>`<option value="${l}">${title(l)}</option>`).join('')}</select></label><label>Questions <select id="c"><option>10</option><option>25</option><option>50</option></select></label></div><button id="go">Start</button><p id="msg" class="warn" hidden></p></div><div id="qz"></div>`;
 root.querySelector('#go').onclick=()=>{const qs=grammarQs(root.querySelector('#l').value,+root.querySelector('#c').value);const m=root.querySelector('#msg');
  if(!qs.length){m.hidden=false;m.textContent='No questions for that scope.';return}m.hidden=qs.length>=+root.querySelector('#c').value;if(!m.hidden)m.textContent=`Only ${qs.length} questions available here; running those.`;
  runQuiz(root.querySelector('#qz'),qs,{title:'Grammar practice',back:'#/grammar',backLabel:'Back to grammar'});root.querySelector('#qz').scrollIntoView()};
}






load();
const routes=[['#/','Dashboard'],['#/kanji','Kanji 1–320'],['#/kanji-quiz','Kanji quizzes'],['#/vocab','Vocabulary'],['#/grammar','Grammar & Particles'],['#/settings','Settings']];
const nav=document.getElementById('nav'),main=document.getElementById('main');
function dashboard(){const c=counts(),s=get(),r=s.results.slice(-5).reverse();
 const today=new Date().toISOString().slice(0,10);const days=[...Array(7)].map((_,i)=>{const d=new Date(Date.now()-(6-i)*864e5).toISOString().slice(0,10);return{d,n:s.log.filter(x=>x.d===d).length}});const mx=Math.max(1,...days.map(x=>x.n));
 const vc=vocabCounts();const gr=Object.values(s.grammar||{}).reduce((a,x)=>[a[0]+x.right,a[1]+x.wrong],[0,0]);const answered=c.right+c.wrong;const nx=nextSuggested();
 main.innerHTML=`<h2>${s.settings.name?'Welcome, '+esc(s.settings.name):'MINNA N5'}</h2><p><i>Study Japanese. Practise every day. Be exam-ready.</i></p>
 <div class="stats"><div class="card stat"><b>${c.studied} / 320</b>kanji studied${bar(pct(c.studied,320))}</div><div class="card stat"><b>${c.mastered}</b>kanji mastered</div><div class="card stat"><b>${c.revision}</b>need revision</div><div class="card stat"><b>${answered}</b>questions answered</div><div class="card stat"><b>${pct(c.right,answered)}%</b>kanji accuracy</div><div class="card stat"><b>${vc.learned} / ${vc.total}</b>vocabulary learned${bar(pct(vc.learned,vc.total))}</div><div class="card stat"><b>${pct(gr[0],gr[0]+gr[1])}%</b>grammar accuracy (${gr[0]+gr[1]} answered)</div></div>
 <div class="card"><h3>This week (questions per day)</h3><div class="row" style="align-items:flex-end;height:110px">${days.map(x=>`<div style="flex:1;text-align:center"><div style="background:var(--purple);height:${Math.round(80*x.n/mx)}px;border-radius:4px 4px 0 0" title="${x.n}"></div><small>${x.d.slice(5)}<br>${x.n}</small></div>`).join('')}</div></div>
 <div class="card"><h3>Suggested next</h3><p><a class="btn" href="#/kanji/${nx}">Kanji ${nx}</a> <a class="btn alt" href="#/kanji-quiz">Take a quiz</a></p></div>
 <div class="card"><h3>Latest scores</h3>${r.length?r.map(x=>`<p>${esc(x.title)}: <b>${x.score}/${x.total}</b> <span class="muted">${x.d.slice(0,10)}</span></p>`).join(''):'<p class="muted">No quizzes taken yet.</p>'}</div>
 <p class="warn">Work in progress: built so far are Kanji 1–320, Vocabulary and Grammar &amp; Particles. Full lesson pages, kana, reading, listening, mock exams and the study plan are not built yet.</p>`;}
function settings(){const s=get().settings;
 main.innerHTML=`<h2>Settings</h2><div class="card"><div class="row"><label>Display name <input id="nm" value="${esc(s.name)}"></label><label>Daily goal (questions) <input id="gl" type="number" min="1" value="${s.goal}" style="width:80px"></label><label>Target exam date <input id="ex" type="date" value="${esc(s.exam)}"></label></div><button id="sv">Save</button></div>
 <div class="card"><h3>Your data</h3><p class="muted">Progress is stored in this browser's LocalStorage only. It does not sync between devices — use export/import to move it.</p>
 <div class="row"><button id="exp">Export progress</button><label class="btn alt">Import progress<input id="imp" type="file" accept="application/json" hidden></label><button class="danger" id="rs">Reset all progress</button></div><p id="m" aria-live="polite"></p></div>`;
 const $=q=>main.querySelector(q);
 $('#sv').onclick=()=>{s.name=$('#nm').value.trim();s.goal=Math.max(1,+$('#gl').value||20);s.exam=$('#ex').value;save();$('#m').textContent='Saved.'};
 $('#exp').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([exportJSON()],{type:'application/json'}));a.download='minna-n5-progress.json';a.click()};
 $('#imp').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const t=await f.text();JSON.parse(t);if(confirm('Replace current progress with this file?')){importJSON(t);$('#m').textContent='Imported.'}}catch(err){$('#m').textContent='Import failed: '+err.message}};
 $('#rs').onclick=()=>{if(confirm('Delete ALL progress? This cannot be undone.')){reset();$('#m').textContent='Progress reset.'}};}
function render(){const h=location.hash||'#/';const p=h.split('/');
 nav.innerHTML=`<h1>MINNA N5</h1><p>Study Japanese. Practise every day.</p>`+routes.map(r=>`<a href="${r[0]}" class="${h===r[0]||(r[0]==='#/kanji'&&/^#\/kanji(\/|-flash)/.test(h))?'on':''}">${r[1]}</a>`).join('');
 nav.classList.remove('open');
 if(h==='#/'||h==='#')dashboard();else if(h==='#/kanji')index(main);else if(p[1]==='kanji'&&p[2])detail(main,p[2]);
 else if(p[1]==='kanji-flash')flash(main,p[2],p[3]);else if(h==='#/kanji-quiz')quizMenu(main);else if(h==='#/vocab')vocabIndex(main);else if(p[1]==='vocab-flash')vocabFlash(main,p[2]);else if(h==='#/vocab-quiz')vocabQuizMenu(main);else if(p[1]==='grammar'&&!p[2])grammarIndex(main);else if(p[1]==='grammar'&&p[2])grammarIndex(main,p[2]);else if(h==='#/grammar-quiz')grammarQuizMenu(main);else if(h==='#/settings')settings();else dashboard();
 main.focus({preventScroll:true});scrollTo(0,0)}
addEventListener('hashchange',render);
document.getElementById('menuBtn').onclick=e=>{const o=nav.classList.toggle('open');e.target.setAttribute('aria-expanded',o)};
render();

window.__minna={VOCAB,vocabQs,grammarQs,GRAMMAR};
})();